import{c as n,$ as e,Q as i,j as s,o,m as d,g as u}from"./chunks/framework.CWBTDBPu.js";const k=JSON.parse('{"title":"YuRandomTeleport 插件介绍","description":"","frontmatter":{"title":"YuRandomTeleport 插件介绍"},"headers":[],"relativePath":"plugins/items/yu-random-teleport/index.md","filePath":"plugins/items/yu-random-teleport/index.md"}'),p={name:"plugins/items/yu-random-teleport/index.md"},h={class:"quick-actions"};function m(g,t,_,P,f,b){const a=e("PluginMeta"),r=e("CopyMarkdownButton"),c=e("CopyLLMButton"),l=e("PluginServerShowcase");return i(),s("div",null,[o(a,{slug:"yu-random-teleport"}),t[0]||(t[0]=d('<div class="quick-actions"><a class="tool-button" href="https://github.com/vicuna-main/YuRTPIssueReport" target="_blank" rel="noopener noreferrer">Bug / Issue 反馈</a><a class="tool-button" href="https://qm.qq.com/q/xiwJYBYdh0" target="_blank" rel="noopener noreferrer">官方 QQ 交流群</a><a class="tool-button" href="https://afdian.com/a/vicuna" target="_blank" rel="noopener noreferrer">爱发电支持作者</a></div><h2 id="文档入口" tabindex="-1">文档入口 <a class="header-anchor" href="#文档入口" aria-label="Permalink to &quot;文档入口&quot;">​</a></h2><p>YuRandomTeleport <code>1.2.0.0</code> 是面向 Minecraft <code>1.8.x-1.26.x</code> 的跨版本安全随机传送插件。新版在原有的世界规则、经济与安全落点能力上，加入 Folia 调度、Paper 异步传送、公开 Java API、可取消生命周期事件、PlaceholderAPI 和多语言系统。</p><div class="doc-card-grid"><a class="doc-mini-card" href="install"><strong>安装部署</strong><span>构建、放置 jar、首次启动、Vault 经济接入和升级检查</span></a><a class="doc-mini-card" href="commands"><strong>命令手册</strong><span>/yurtp 与 /rtp 的玩家用法、管理员代传送和重载命令</span></a><a class="doc-mini-card" href="config"><strong>配置说明</strong><span>世界黑白名单、半径、高度、安全方块、等待打断和自定义控制台命令</span></a><a class="doc-mini-card" href="permissions"><strong>权限节点</strong><span>普通玩家、管理员、绕过冷却、绕过费用和跳过等待</span></a><a class="doc-mini-card" href="placeholders"><strong>PlaceholderAPI</strong><span>冷却、状态、平台、统计和最近传送位置变量</span></a><a class="doc-mini-card" href="events"><strong>Bukkit 事件</strong><span>开始、目标点、取消与完成四个传送生命周期事件</span></a><a class="doc-mini-card" href="api"><strong>Java API</strong><span>异步请求、主动取消、快照、计数器与平台检测</span></a><a class="doc-mini-card" href="faq"><strong>常见问题</strong><span>找不到安全点、无法扣费、等待被取消、下界配置和世界限制排查</span></a></div>',4)),u("div",h,[o(r,{slug:"yu-random-teleport"}),o(c,{slug:"yu-random-teleport"})]),t[1]||(t[1]=d('<h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>广版本与混合端适配</td><td>面向 <code>1.8.x-1.26.x</code>，覆盖 Spigot、Paper、Paper 衍生端，并兼顾 Mohist、Arclight、Youer 等混合端运行环境。</td></tr><tr><td>安全随机传送</td><td>在配置半径内随机抽取 X/Z，加载区块后检查脚下方块、脚部空间、头部空间和头顶额外空气。</td></tr><tr><td>主世界与下界适配</td><td>普通世界使用最高地表作为候选点；下界会在高度范围内随机扫描 Y 轴，避免只抽少量高度导致卡墙。</td></tr><tr><td>世界访问控制</td><td>支持 <code>world-blacklist</code> 黑名单和 <code>world-whitelist</code> 白名单；白名单非空时优先生效。</td></tr><tr><td>按世界覆盖</td><td>每个世界可单独设置费用、半径、高度、安全检查、禁止方块和允许方块。</td></tr><tr><td>等待与打断</td><td>可配置传送前等待秒数；移动、受伤、交互、聊天、执行命令或离线可取消等待中的传送。</td></tr><tr><td>冷却与扣费</td><td>内置冷却；开启经济后通过 Vault 调用服务端经济插件扣费。</td></tr><tr><td>自定义反馈</td><td>可在传送开始、成功、失败时由控制台执行命令，适合接入 title、音效、广播、任务或日志系统。</td></tr><tr><td>Folia / Paper 调度</td><td>Folia 下按 Global、Region、Entity Scheduler 分派；Paper/Purpur 支持可用时调用 <code>teleportAsync</code>。</td></tr><tr><td>插件开发接口</td><td>通过 Bukkit <code>ServicesManager</code> 暴露异步 Java API，并提供 4 个生命周期事件。</td></tr><tr><td>PlaceholderAPI</td><td>可选注册 <code>%yurtp_*%</code>，只读取无锁快照，不触发区块加载或 Vault 查询。</td></tr><tr><td>多语言</td><td>内置简体中文与英语，可按玩家客户端语言选择，并支持 <code>lang/</code> 自定义语言文件。</td></tr><tr><td>自动配置升级</td><td>插件按 <code>config-version</code> 合并默认配置并保留已有值；旧 <code>messages.yml</code> 可继续覆盖中文文本。</td></tr><tr><td>统计接入</td><td>内置 bStats Bukkit 统计，插件 ID 为 <code>30589</code>。</td></tr></tbody></table><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><ol><li>构建或获取发布版 <code>YuRandomTeleport-1.2.0.0-all.jar</code>。</li><li>将 jar 放入服务端 <code>plugins/</code> 目录并启动一次服务器。</li><li>打开 <code>plugins/YuRandomTeleport/config.yml</code>，确认 <code>world-blacklist</code>、半径和安全规则。</li><li>普通玩家使用 <code>/rtp</code> 或 <code>/yurtp</code> 在当前世界随机传送。</li><li>管理员可用 <code>/yurtp &lt;玩家&gt; [世界]</code> 将指定玩家随机传送到指定世界。</li><li>修改配置或语言文件后执行 <code>/yurtp reload</code> 热重载。</li></ol><h2 id="适合的服务器" tabindex="-1">适合的服务器 <a class="header-anchor" href="#适合的服务器" aria-label="Permalink to &quot;适合的服务器&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>推荐用法</th></tr></thead><tbody><tr><td>生存服</td><td>允许玩家离开主城后快速分散探索，设置合理冷却和等待打断。</td></tr><tr><td>资源世界</td><td>使用白名单只允许 <code>resource</code>、<code>resource_nether</code> 等世界执行随机传送。</td></tr><tr><td>经济服</td><td>开启 Vault 扣费，对不同世界设置不同成本。</td></tr><tr><td>活动服</td><td>使用 <code>commands.on-success</code> 发放标题、记录日志或触发活动系统。</td></tr><tr><td>高版本大地图</td><td>保持安全检查开启，并按世界设置高度范围和禁止方块。</td></tr></tbody></table><h2 id="当前版本定位" tabindex="-1">当前版本定位 <a class="header-anchor" href="#当前版本定位" aria-label="Permalink to &quot;当前版本定位&quot;">​</a></h2><ul><li>插件版本：<code>1.2.0.0</code></li><li>主类：<code>org.yutay.yurtp.YuRandomTeleport</code></li><li>主命令：<code>/yurtp</code></li><li>别名：<code>/rtp</code></li><li>Java 目标版本：Java 8</li><li>兼容定位：Minecraft <code>1.8.x-1.26.x</code>，Bukkit/Spigot/Paper/Purpur/Folia 与兼容 Bukkit API 的混合端</li><li>已测试：Paper <code>1.8.8</code>、<code>1.12.2</code>、<code>1.16.5</code>、<code>1.21.1</code>、<code>1.26.2</code>；Purpur <code>1.21.1</code>；Folia <code>1.20.1</code>；Youer <code>1.21.1</code></li><li>软依赖：Vault、PlaceholderAPI</li><li>Folia 声明：<code>folia-supported: true</code></li><li>bStats 插件 ID：<code>30589</code></li><li>默认配置版本：<code>config-version: 9</code></li><li>内置语言：<code>zh_CN</code>、<code>en_US</code></li></ul><h2 id="使用该插件的服务器" tabindex="-1">使用该插件的服务器 <a class="header-anchor" href="#使用该插件的服务器" aria-label="Permalink to &quot;使用该插件的服务器&quot;">​</a></h2>',9)),o(l,{slug:"yu-random-teleport"})])}const x=n(p,[["render",m]]);export{k as __pageData,x as default};
